class StreamChecker {
    private int[][] trie;
    private boolean[] end;
    private int cnt = 0;
    private StringBuilder sb = new StringBuilder();
    public StreamChecker(String[] words) {
        trie = new int[200 * 2000 + 1][26];
        end = new boolean[200 * 2000 + 1];
        for (int[] row : trie) java.util.Arrays.fill(row, -1);
        for (String w : words) {
            int node = 0;
            for (int i = w.length() - 1; i >= 0; i--) {
                int c = w.charAt(i) - 'a';
                if (trie[node][c] == -1) trie[node][c] = ++cnt;
                node = trie[node][c];
            }
            end[node] = true;
        }
    }
    public boolean query(char letter) {
        sb.append(letter);
        int node = 0;
        for (int i = sb.length() - 1; i >= 0; i--) {
            int c = sb.charAt(i) - 'a';
            if (trie[node][c] == -1) return false;
            node = trie[node][c];
            if (end[node]) return true;
        }
        return false;
    }
}

import java.util.*;

class StreamChecker {
    private int[][] go;
    private int[] fail;
    private boolean[] output;
    private int size;
    private int state;

    public StreamChecker(String[] words) {
        int maxNodes = 1;
        for (String w : words) maxNodes += w.length();
        go = new int[maxNodes][26];
        fail = new int[maxNodes];
        output = new boolean[maxNodes];
        for (int[] row : go) Arrays.fill(row, -1);
        size = 1;
        for (String w : words) {
            int cur = 0;
            for (int i = 0; i < w.length(); i++) {
                int c = w.charAt(i) - 'a';
                if (go[cur][c] == -1) go[cur][c] = size++;
                cur = go[cur][c];
            }
            output[cur] = true;
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int c = 0; c < 26; c++) {
            if (go[0][c] == -1) go[0][c] = 0;
            else { fail[go[0][c]] = 0; queue.offer(go[0][c]); }
        }
        while (!queue.isEmpty()) {
            int u = queue.poll();
            output[u] = output[u] || output[fail[u]];
            for (int c = 0; c < 26; c++) {
                if (go[u][c] == -1) {
                    go[u][c] = go[fail[u]][c];
                } else {
                    fail[go[u][c]] = go[fail[u]][c];
                    queue.offer(go[u][c]);
                }
            }
        }
        state = 0;
    }

    public boolean query(char letter) {
        state = go[state][letter - 'a'];
        return output[state];
    }
}
